$r=az vm run-command invoke -g rg-lab513-vm -n lab513vm --command-id RunPowerShellScript --scripts "if(-not(Test-Path 'C:\Program Files\Python312\python.exe')){iwr 'https://www.python.org/ftp/python/3.12.7/python-3.12.7-amd64.exe' -OutFile \$env:TEMP\py.exe; Start-Process \$env:TEMP\py.exe -ArgumentList '/quiet','InstallAllUsers=1','PrependPath=1','Include_pip=1' -Wait}; New-Item -ItemType Directory -Force C:\Tools|Out-Null; if(-not(Test-Path 'C:\Tools\devtunnel.exe')){iwr 'https://aka.ms/TunnelsCliDownload/win-x64' -OutFile C:\Tools\devtunnel.exe}; \$m=[Environment]::GetEnvironmentVariable('Path','Machine'); if(\$m -notlike '*C:\Tools*'){[Environment]::SetEnvironmentVariable('Path','C:\Tools;'+\$m,'Machine')}; 'py='+(Test-Path 'C:\Program Files\Python312\python.exe')+'; dt='+(Test-Path 'C:\Tools\devtunnel.exe')" -o json | ConvertFrom-Json
$r.value[0].message
